        "marks": 1,
        "frequency": "Rare",
        "text": "When a top-down approach of dynamic programming is applied to a problem, it usually ______\ni. Decreases both the time complexity and the space complexity\nii. Decreases the time complexity and increases the space complexity\niii. Increases the time complexity and decreases the space complexity\niv. Increases both the time complexity and the space complexity",
        "concept": "Top-down DP (memoization) time-space trade-off",
        "blueprint": ""
