        "qNumber": "1",
        "subPart": "f",
        "marks": 1,
        "frequency": "High-Yield",
        "text": "Consider the functions f(n) = 3n^sqrt(n), g(n) = 2^(sqrt(n) log2 n), h(n) = n!. Which of the following is/are true?\ni. h(n) = Theta(f(n))\nii. h(n) = Theta(g(n))\niii. f(n) = Theta(g(n))\niv. g(n) != Theta(f(n))",
