        "marks": 1,
        "frequency": "Regular",
        "text": "Let G be an edge-weighted undirected graph with positive edge weights. Suppose a positive constant a is added to the weight of every edge. Which ONE of the following statements is TRUE about the MSTs and shortest paths (SPs) in G before and after the edge weight update?\ni. Every MST remains an MST, and every SP remains an SP.\nii. MSTs need not remain MSTs, and every SP remains an SP.\niii. Every MST remains an MST, and SPs need not remain SPs.\niv. MSTs need not remain MSTs, and SPs need not remain SPs.",
        "concept": "Effect of adding constant to all edge weights on MST",
        "blueprint": ""
