        "subPart": "h",
        "marks": 1,
        "frequency": "Regular",
        "text": "Consider the C fragment (i, j, n integers):\ni = n;\nfor (j = 0; i > 0; i /= 2) j += i;\nLet val(j) denote the value stored in j after termination of the loop. Find the tightest asymptotic bound for val(j).",
