        "text": "In a Stop-and-Wait system, the bandwidth of the line is 1 Mbps, and 1 bit takes 20 milliseconds to make a round trip. What is the bandwidth-delay product? If the system data packets are 1,000 bits in length, (1) what is the utilization percentage of the link? (2) What is the utilization percentage of the link in (1) if we have a protocol that can send up to 15 packets before stopping and worrying about the acknowledgments?",
