        "text": "Here are four options for improving web page performance: Option 1: HTTP caching with a forward proxy; Option 2: CDN using DNS; Option 3: CDN using anycast; Option 4: CDN based on rewriting HTML URLs. You have been asked to help reduce the costs for networking at KIIT University, whose online course delivery has led to a significant increase in network costs. Select one option to minimize server load. Compare the operation of each option and justify a selection that provides the finest granularity of control over load to the content servers and a selection that will serve each customer from the closest CDN server.",
